package com.shatteredpixel.shatteredpixeldungeon.apd.query.research;
import com.shatteredpixel.shatteredpixeldungeon.apd.query.*;
import com.shatteredpixel.shatteredpixeldungeon.apd.stats.*;
import org.junit.Test;
import static org.junit.Assert.*;
public class RunLuckTest {
    @Test public void empiricalPercentileUsesTenIndependentPeersAndMidRanks(){ResearchFixture f=new ResearchFixture();Row a=f.add("subject","mage",0,0);f.num(a,CustomRuleFacts.GENERATED_UPGRADES,4);for(int i=0;i<10;i++){Row r=f.add("p"+i,"mage",0,0);f.num(r,CustomRuleFacts.GENERATED_UPGRADES,i<5?3:4);}RunLuck.Result l=RunLuck.build(f.result(),a);assertEquals(10,l.peers.size());RunLuck.Metric m=l.metrics.get(0);assertEquals(75,m.percentile,0);assertEquals(5,m.below);assertEquals(5,m.tied);assertEquals(3.5,m.mean,0);}
    @Test public void settingsVersionsProgressAndRepeatedSeedsNeverMix(){ResearchFixture f=new ResearchFixture();Row a=f.add("subject","mage",0,0);Row v=f.add("version","mage",0,0);f.text(v,"run.apdVersion","v2");Row settings=f.add("settings","mage",0,0);f.text(settings,CustomRuleFacts.IDENTITY,"different");Row depth=f.add("depth","mage",0,0);f.num(depth,"result.deepest",6);Row seed=f.add("seed","mage",0,0);f.num(seed,"run.seed",1);f.add("class","warrior",0,0);Row daily=f.add("daily","mage",0,0);f.num(daily,"run.seedType",2);assertEquals(0,RunLuck.build(f.result(),a).peers.size());}
    @Test public void hiddenAndUnfinishedGenerationNeverLeaks(){ResearchFixture f=new ResearchFixture();Row a=f.add("subject","mage",0,0);assertFalse(RunLuck.build(f.result(f.query().withShowInternal(false)),a).unavailable.isEmpty());a.finished=false;assertFalse(RunLuck.build(f.result(),a).unavailable.isEmpty());}
    @Test public void tooSmallAndIncompleteReferencesHaveNoPercentile(){ResearchFixture f=new ResearchFixture();Row a=f.add("subject","mage",0,0);for(int i=0;i<10;i++)f.add("p"+i,"mage",0,0);f.rows.get(1).setNum(f.def.indexOf(CustomRuleFacts.GENERATED_UPGRADES),3,Fact.PROV_INCOMPLETE);RunLuck.Metric m=RunLuck.build(f.result(),a).metrics.get(0);assertEquals(9,m.n);assertEquals(1,m.excluded);assertTrue(Double.isNaN(m.percentile));}
    @Test public void filtersAndRecordedScoresRemainUnchanged(){ResearchFixture f=new ResearchFixture();Row a=f.add("subject","mage",0,1234);f.add("other","warrior",0,5678);Query q=f.forClass("mage");assertEquals(0,RunLuck.build(f.result(q),a).peers.size());assertEquals(1234,a.num(f.def.indexOf("result.score")));assertEquals(q,f.result(q).query);}
    @Test public void duplicateAndImportedRecordsDoNotBecomeReferenceRuns(){ResearchFixture f=new ResearchFixture();Row a=f.add("subject","mage",0,0);f.add("duplicate","mage",0,0).duplicate=true;f.add("import","mage",0,0).imported=true;assertEquals(0,RunLuck.build(f.result(),a).peers.size());assertNull(RunLuck.build(f.result(f.forClass("warrior")),a));}
}
